import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class LengthPrefixDecoderDemo {
    private static final int HEADER_LEN = 4;           // length 字段 4 字节
    private static final int MAX_FRAME = 8 * 1024 * 1024; // 8MB 安全上限
    private byte[] cumulation = new byte[0];           // 累积缓冲区

    /**
     * 每次 channelRead 送入一批字节，返回本次解出的完整消息列表。
     * 残留字节留在 cumulation 等下次。
     */
    List<String> decode(byte[] in) {
        // 1. 追加到累积缓冲区
        byte[] merged = new byte[cumulation.length + in.length];
        System.arraycopy(cumulation, 0, merged, 0, cumulation.length);
        System.arraycopy(in, 0, merged, cumulation.length, in.length);
        cumulation = merged;

        List<String> out = new ArrayList<>();
        int offset = 0;
        // 2. 循环尝试提取完整 frame
        while (cumulation.length - offset >= HEADER_LEN) {
            // 3. peek length（不消费指针）
            int length = ByteBuffer.wrap(cumulation, offset, HEADER_LEN).getInt();
            // 4. maxFrameLength 安全检查
            if (length < 0 || length > MAX_FRAME) {
                throw new IllegalArgumentException("bad frame length: " + length);
            }
            // 5. body 是否到齐
            if (cumulation.length - offset < HEADER_LEN + length) break;
            // 6. emit 完整 frame
            int bodyStart = offset + HEADER_LEN;
            out.add(new String(cumulation, bodyStart, length, StandardCharsets.UTF_8));
            offset += HEADER_LEN + length;
        }
        // 7. 只丢弃已 emit 的部分，残留留在 cumulation
        cumulation = Arrays.copyOfRange(cumulation, offset, cumulation.length);
        return out;
    }

    static byte[] frame(String body) {
        byte[] payload = body.getBytes(StandardCharsets.UTF_8);
        return ByteBuffer.allocate(HEADER_LEN + payload.length)
                .putInt(payload.length)
                .put(payload)
                .array();
    }

    static byte[] concat(byte[]... chunks) {
        int size = 0;
        for (byte[] chunk : chunks) size += chunk.length;
        byte[] out = new byte[size];
        int offset = 0;
        for (byte[] chunk : chunks) {
            System.arraycopy(chunk, 0, out, offset, chunk.length);
            offset += chunk.length;
        }
        return out;
    }

    public static void main(String[] args) {
        LengthPrefixDecoderDemo decoder = new LengthPrefixDecoderDemo();
        byte[] ping = frame("PING");   // 4+4=8 字节
        byte[] pong = frame("PONG");   // 4+4=8 字节
        byte[] hello = frame("HELLO"); // 4+5=9 字节

        // 场景 1：只收到 ping 的前 2 字节（length 字段不完整）→ 无输出
        System.out.println(decoder.decode(Arrays.copyOfRange(ping, 0, 2)));
        // 场景 2：收到 ping 剩余 6 字节 + pong 完整 8 字节 → 输出 PING, PONG
        System.out.println(decoder.decode(
                concat(Arrays.copyOfRange(ping, 2, ping.length), pong)));
        // 场景 3：收到 hello 的前 7 字节（length 已完整但 body 不全）→ 无输出
        System.out.println(decoder.decode(Arrays.copyOfRange(hello, 0, 7)));
        // 场景 4：收到 hello 剩余 2 字节 → 输出 HELLO
        System.out.println(decoder.decode(Arrays.copyOfRange(hello, 7, hello.length)));
    }
}
